        assertEquals(201, company.statusCode());
        JsonNode created = json.readTree(company.body());
        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
        assertTrue(created.get("guestCpf").isNull());
        assertTrue(created.get("guestPassport").isNull());
        long id = created.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("ISS retido (5%): R$ 46,79"));
        assertTrue(json.readTree(get("/messages").body()).get(0).get("body").asText()
                .contains("Empresa: Tecnosul Ltda"));

        HttpResponse<String> passport = post("/reservations", reservationWith(
                "\"guestPassport\": \"X1234567\", \"guestCountry\": \"United Kingdom\",")
                .replace("2027-07-1", "2027-08-1"));
        assertEquals(201, passport.statusCode());
        assertEquals("United Kingdom", json.readTree(passport.body()).get("guestCountry").asText());
    }

    @Test
    void refusesAGuestIdentifiedInNoWayOrInMoreThanOne() throws Exception {
        for (String identification : new String[] {
                "",
                "\"guestCpf\": \"111.222.333-44\", \"guestPassport\": \"X1\", \"guestCountry\": \"UK\",",
                "\"guestCpf\": \"111.222.333-44\", \"companyCnpj\": \"1\", \"companyName\": \"A\",",
                "\"companyCnpj\": \"12.345.678/0001-90\",",
                "\"guestPassport\": \"X1234567\","}) {
            HttpResponse<String> response = post("/reservations", reservationWith(identification));
            assertEquals(400, response.statusCode(), identification);
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }
    }
EOF
